PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?iri ?title WHERE {
  ?iri rdf:type ?type ;
       rdfs:label ?title .
  FILTER(CONTAINS(STR(?type), "Requirement"))
}
ORDER BY LCASE(STR(?title))

